<script setup lang="ts">
import {Heart,MoreHorizontal,ChevronDown} from 'lucide-vue-next';
import TreeholeAvatar from './TreeholeAvatar.vue';
import {treeholeTimestamp} from '../domain/treeholePresentation';
import type {TreeholeComment} from '../services/treehole';
const props=defineProps<{comment:TreeholeComment;busy:boolean;locked:boolean;expanded?:boolean;more?:boolean}>();
defineEmits<{reply:[comment:TreeholeComment];like:[comment:TreeholeComment];menu:[comment:TreeholeComment];expand:[]}>();
function replyName(c:TreeholeComment){return c.replyTo===props.comment.id?'':props.comment.replies?.find(x=>x.id===c.replyTo)?.author.name||'评论';}
</script>
<template><article class="th-comment" :class="{'is-deleted':comment.deleted}"><TreeholeAvatar :name="comment.author.name" :anonymous="comment.author.anonymous" :size="32"/><div class="th-comment-content"><header><div><strong>{{comment.author.name}}<em v-if="comment.isOriginalPoster">楼主</em><em v-else-if="comment.author.mine">我</em></strong><small>{{treeholeTimestamp(comment.createdAt)}}</small></div><button v-if="!comment.deleted" class="th-comment-like" :aria-label="comment.liked?'取消评论点赞':'点赞评论'" :aria-pressed="!!comment.liked" :disabled="busy" @click="$emit('like',comment)"><Heart :size="15" :fill="comment.liked?'currentColor':'none'"/>{{comment.likeCount||''}}</button><button v-if="!comment.deleted" class="th-comment-menu" aria-label="评论操作" :disabled="busy" @click="$emit('menu',comment)"><MoreHorizontal :size="16"/></button></header><p class="th-full-body">{{comment.body}}</p><button v-if="!comment.deleted&&!locked" class="th-reply" :disabled="busy" @click="$emit('reply',comment)">回复</button><div v-if="comment.replies?.length||(comment.replyCount||0)>0" class="th-replies"><div v-for="child in comment.replies" :key="child.id" class="th-nested-reply"><button class="th-reply-text" :disabled="busy||locked||child.deleted" @click="$emit('reply',child)"><strong>{{child.author.name}}<em v-if="child.isOriginalPoster">楼主</em></strong><span v-if="replyName(child)" class="th-reply-quote"> 回复 {{replyName(child)}}</span>：{{child.body}}</button><div class="th-reply-meta"><small>{{treeholeTimestamp(child.createdAt)}}</small><button v-if="!child.deleted" :aria-label="child.liked?'取消评论点赞':'点赞评论'" :aria-pressed="!!child.liked" :disabled="busy" @click="$emit('like',child)"><Heart :size="13" :fill="child.liked?'currentColor':'none'"/>{{child.likeCount||''}}</button><button v-if="!child.deleted" aria-label="回复操作" :disabled="busy" @click="$emit('menu',child)"><MoreHorizontal :size="16"/></button></div></div><button v-if="!expanded||more" class="th-expand-replies" :disabled="busy" @click="$emit('expand')">{{expanded?'加载更多回复':'全部 '+comment.replyCount+' 条回复'}}<ChevronDown :size="15"/></button></div></div></article></template>
<style scoped>
.th-comment{display:flex;align-items:flex-start;gap:10px;padding:21px 0;border-bottom:1px solid var(--color-divider)}.th-comment:last-child{border:0}.th-comment-content{flex:1;min-width:0}header{display:flex;align-items:flex-start;gap:7px}header>div{flex:1;min-width:0}strong{font-weight:550;font-size:13px;overflow-wrap:anywhere}em{font-style:normal;font-size:9px;padding:1px 4px;margin-left:5px;background:var(--color-tint);color:var(--color-primary);border-radius:3px}small{font-size:10px;color:var(--color-muted);display:block;margin-top:5px}.th-comment-like,.th-comment-menu{display:flex;align-items:center;justify-content:center;gap:4px;min-height:30px;color:var(--color-muted);font-size:11px}.th-comment-menu{width:24px}button[aria-pressed=true]{color:var(--color-primary)}.th-full-body{font-size:15px;line-height:1.8;white-space:pre-wrap;overflow-wrap:anywhere;margin:10px 0 4px}.is-deleted .th-full-body{color:var(--color-muted)}.th-reply{min-height:30px;color:var(--color-muted);font-size:11px}.th-replies{background:var(--color-bg);border-radius:6px;padding:9px 10px 0;margin-top:8px}.th-nested-reply{padding:4px 0 7px}.th-reply-text{text-align:left;font-size:13px;line-height:1.8;overflow-wrap:anywhere;white-space:pre-wrap;width:100%}.th-reply-text strong{color:var(--color-primary);font-size:12px}.th-reply-quote{font-size:12px;color:var(--color-muted)}.th-reply-meta{display:flex;align-items:center;gap:9px;color:var(--color-muted)}.th-reply-meta small{flex:1;margin:0}.th-reply-meta button{display:flex;align-items:center;gap:3px;min-height:24px;font-size:10px}.th-expand-replies{display:flex;gap:5px;align-items:center;justify-content:center;width:100%;min-height:39px;color:var(--color-muted);font-size:12px;border-top:1px solid var(--color-divider)}
</style>
